<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id']))redirect('index.php');
require_once dirname(__DIR__).'/private/operations.php';require_once dirname(__DIR__).'/private/ui.php';
$id=max(0,(int)($_GET['id']??0));$search=mb_substr(trim((string)($_GET['q']??'')),0,190);$page=max(1,min(10000,(int)($_GET['page']??1)));$archived=isset($_GET['archived']);
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{if(($_POST['action']??'')==='save')$id=opsSaveCustomer($pdo,(int)$_SESSION['admin_id'],$_POST,$id);elseif(($_POST['action']??'')==='archive')opsCustomerArchive($pdo,(int)$_SESSION['admin_id'],$id,!empty($_POST['archive']),opsVersion($_POST));else throw new InvalidArgumentException('Aktion unbekannt.');$_SESSION['app_notice']='Kundendaten gespeichert; bestehende Rechnungen bleiben unverändert.';}catch(Throwable $e){gszUiError($e);}redirect('customers.php'.($id?'?id='.$id:''));}
$customer=null;$list=[];$history=[];$properties=[];$more=false;
try{opsRequire($pdo);if($id){$q=$pdo->prepare('SELECT * FROM customers WHERE id=?');$q->execute([$id]);$customer=$q->fetch();if(!$customer){http_response_code(404);exit('Kunde nicht gefunden.');}$history=opsHistory($pdo,'customer',$id);$q=$pdo->prepare('SELECT id,name,address FROM properties WHERE customer_id=? ORDER BY name LIMIT 100');$q->execute([$id]);$properties=$q->fetchAll();}
 $where=$archived?'1=1':'archived_at IS NULL';$q=$pdo->prepare("SELECT id,name,email,phone,archived_at FROM customers WHERE $where AND (name LIKE ? OR email LIKE ?) ORDER BY name,id LIMIT 31 OFFSET ".(($page-1)*30));$q->execute(['%'.$search.'%','%'.$search.'%']);$list=$q->fetchAll();$more=count($list)>30;$list=array_slice($list,0,30);
}catch(Throwable $e){gszUiError($e);}gszPageStart('Kundenverwaltung');
?><p>Kundenstammdaten bearbeiten; ausgestellte Dokumente behalten ihren gespeicherten Empfängerstand.</p><form method="get"><label>Suche<input name="q" value="<?=e($search)?>"></label><label><input type="checkbox" name="archived" <?=$archived?'checked':''?>> Archivierte einschließen</label><button>Suchen</button></form><p><a href="customers.php?new=1">Neuen Kunden anlegen</a></p>
<?php if($customer||isset($_GET['new'])):$c=$customer?:[];?><section class="card"><h2><?=$customer?'Kunde bearbeiten':'Neuer Kunde'?></h2><?php if(empty($c['archived_at'])):?><form method="post"><?php gszFields('save');?><input type="hidden" name="row_version" value="<?=(int)($c['row_version']??0)?>"><label>Name<input name="name" maxlength="190" value="<?=e($c['name']??'')?>" required></label><label>E-Mail<input type="email" name="email" maxlength="190" value="<?=e($c['email']??'')?>"></label><label>Telefon<input name="phone" maxlength="80" value="<?=e($c['phone']??'')?>"></label><label>Rechnungsanschrift<textarea name="billing_address" maxlength="2000"><?=e($c['billing_address']??'')?></textarea></label><label>Notizen<textarea name="notes" maxlength="5000"><?=e($c['notes']??'')?></textarea></label><button>Kundendaten speichern</button></form><?php endif?><?php if($customer):?><form method="post"><?php gszFields('archive');?><input type="hidden" name="row_version" value="<?=(int)$c['row_version']?>"><input type="hidden" name="archive" value="<?=empty($c['archived_at'])?'1':'0'?>"><button><?=empty($c['archived_at'])?'Kunden archivieren (keine Löschung)':'Kunden wieder aktivieren'?></button></form><h3>Verknüpfte Objekte</h3><?php foreach($properties as $p):?><p><a href="property.php?id=<?=(int)$p['id']?>"><?=e($p['name'])?></a> · <?=e($p['address'])?></p><?php endforeach?><h3>Letzte Änderungen</h3><?php foreach($history as $h):?><details><summary><?=e($h['created_at'].' UTC · '.$h['action'])?></summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere"><?=e($h['changes_json'])?></pre></details><?php endforeach?><?php endif?></section><?php endif?>
<section class="card"><?php foreach($list as $c):?><article class="task-row"><a href="customers.php?id=<?=(int)$c['id']?>"><?=e($c['name'])?></a><p><?=e($c['email'].' · '.$c['phone'])?> <?=empty($c['archived_at'])?'':'· Archiviert'?></p></article><?php endforeach?></section><nav><?php if($page>1):?><a href="?q=<?=e(rawurlencode($search))?>&amp;page=<?=$page-1?><?=$archived?'&amp;archived=1':''?>">Zurück</a><?php endif?> <?php if($more):?><a href="?q=<?=e(rawurlencode($search))?>&amp;page=<?=$page+1?><?=$archived?'&amp;archived=1':''?>">Weitere Kunden</a><?php endif?></nav><?php gszPageEnd();?>
